namespace RecipeHub.Services;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
    public int TotalRating { get; set; }
    public int RatingCount { get; set; }
    public double AverageRating => RatingCount > 0 ? (double)TotalRating / RatingCount : 0;
}

public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private int _nextId;

    public RecipeService()
    {
        _recipes = new List<Recipe>
        {
            new() { Id = 1, Title = "Classic Margherita Pizza", Category = "Italian", Ingredients = "Pizza dough, San Marzano tomatoes, Fresh mozzarella, Basil, Olive oil", Steps = "1. Preheat oven to 475°F.\n2. Roll out dough.\n3. Spread crushed tomatoes.\n4. Add torn mozzarella.\n5. Bake 10-12 minutes.\n6. Top with fresh basil." },
            new() { Id = 2, Title = "Spaghetti Carbonara", Category = "Italian", Ingredients = "Spaghetti, Guanciale, Eggs, Pecorino Romano, Black pepper", Steps = "1. Cook pasta al dente.\n2. Crisp guanciale in a pan.\n3. Whisk eggs with pecorino.\n4. Toss hot pasta with guanciale.\n5. Remove from heat, stir in egg mixture.\n6. Season with pepper." },
            new() { Id = 3, Title = "Chicken Tikka Masala", Category = "Indian", Ingredients = "Chicken thighs, Yogurt, Garam masala, Tomato sauce, Cream, Ginger, Garlic", Steps = "1. Marinate chicken in yogurt and spices.\n2. Grill or broil chicken pieces.\n3. Sauté onions, ginger, and garlic.\n4. Add tomato sauce and spices.\n5. Simmer, add cream.\n6. Add chicken, cook 5 minutes." },
            new() { Id = 4, Title = "Vegetable Biryani", Category = "Indian", Ingredients = "Basmati rice, Mixed vegetables, Biryani masala, Saffron, Fried onions, Ghee, Mint", Steps = "1. Soak and parboil rice.\n2. Cook vegetables with spices.\n3. Layer rice and vegetables.\n4. Add saffron milk and ghee.\n5. Seal and cook on low heat 20 minutes.\n6. Garnish with fried onions and mint." },
            new() { Id = 5, Title = "Beef Tacos", Category = "Mexican", Ingredients = "Ground beef, Taco seasoning, Corn tortillas, Lettuce, Tomato, Cheese, Sour cream", Steps = "1. Brown ground beef.\n2. Add taco seasoning and water.\n3. Simmer until thickened.\n4. Warm tortillas.\n5. Assemble with toppings.\n6. Serve with lime wedges." },
            new() { Id = 6, Title = "Guacamole", Category = "Mexican", Ingredients = "Avocados, Lime juice, Red onion, Cilantro, Jalapeño, Salt, Tomato", Steps = "1. Halve and pit avocados.\n2. Mash to desired consistency.\n3. Stir in lime juice and salt.\n4. Fold in diced onion, tomato, cilantro.\n5. Add minced jalapeño to taste.\n6. Serve immediately with chips." },
            new() { Id = 7, Title = "Chocolate Lava Cake", Category = "Desserts", Ingredients = "Dark chocolate, Butter, Eggs, Sugar, Flour, Vanilla extract", Steps = "1. Melt chocolate and butter together.\n2. Whisk eggs and sugar until fluffy.\n3. Fold in chocolate mixture.\n4. Add flour and vanilla.\n5. Pour into greased ramekins.\n6. Bake at 425°F for 12 minutes." },
            new() { Id = 8, Title = "Tiramisu", Category = "Desserts", Ingredients = "Ladyfingers, Mascarpone, Espresso, Eggs, Sugar, Cocoa powder, Marsala wine", Steps = "1. Brew and cool espresso.\n2. Whisk egg yolks with sugar.\n3. Fold in mascarpone.\n4. Whip egg whites, fold in.\n5. Dip ladyfingers in espresso.\n6. Layer with cream, dust with cocoa." },
        };
        _nextId = 9;
    }

    public IReadOnlyList<string> GetCategories()
    {
        return _recipes.Select(r => r.Category).Distinct().OrderBy(c => c).ToList();
    }

    public IReadOnlyList<Recipe> GetByCategory(string category)
    {
        return _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();
    }

    public Recipe? GetById(int id)
    {
        return _recipes.FirstOrDefault(r => r.Id == id);
    }

    public void AddRating(int recipeId, int stars)
    {
        var recipe = _recipes.FirstOrDefault(r => r.Id == recipeId);
        if (recipe is not null && stars >= 1 && stars <= 5)
        {
            recipe.TotalRating += stars;
            recipe.RatingCount++;
        }
    }

    public void AddRecipe(string title, string category, string ingredients, string steps)
    {
        _recipes.Add(new Recipe
        {
            Id = _nextId++,
            Title = title,
            Category = category,
            Ingredients = ingredients,
            Steps = steps
        });
    }
}

