@page "/category/{CategoryName}"
@using RecipeHub.Services
@inject RecipeService RecipeService

<PageTitle>@CategoryName Recipes - RecipeHub</PageTitle>

<h1>@CategoryName Recipes</h1>

@if (recipes.Count == 0)
{
    <p>No recipes found in this category.</p>
}
else
{
    <div class="row mt-3">
        @foreach (var recipe in recipes)
        {
            <div class="col-md-6 mb-3">
                <div class="card">
                    <div class="card-body">
                        <h5 class="card-title">@recipe.Title</h5>
                        <p class="card-text text-muted">
                            @if (recipe.RatingCount > 0)
                            {
                                <span>@recipe.AverageRating.ToString("F1") ★ (@recipe.RatingCount ratings)</span>
                            }
                            else
                            {
                                <span>No ratings yet</span>
                            }
                        </p>
                        <a href="recipe/@recipe.Id" class="btn btn-outline-primary">View Recipe</a>
                    </div>
                </div>
            </div>
        }
    </div>
}

<a href="/" class="btn btn-secondary mt-3">← Back to Categories</a>

@code {
    [Parameter]
    public string CategoryName { get; set; } = string.Empty;

    private IReadOnlyList<Recipe> recipes = [];

    protected override void OnParametersSet()
    {
        recipes = RecipeService.GetByCategory(CategoryName);
    }
}

@page "/recipe/{Id:int}"
@using RecipeHub.Services
@inject RecipeService RecipeService

<PageTitle>@(recipe?.Title ?? "Recipe") - RecipeHub</PageTitle>

@if (recipe is null)
{
    <h1>Recipe Not Found</h1>
    <p>The recipe you're looking for doesn't exist.</p>
}
else
{
    <h1>@recipe.Title</h1>
    <p class="text-muted">Category: <a href="category/@recipe.Category">@recipe.Category</a></p>

    <StarRating RecipeId="recipe.Id" CurrentAverage="recipe.AverageRating" RatingCount="recipe.RatingCount" />

    <h3 class="mt-4">Ingredients</h3>
    <ul>
        @foreach (var ingredient in recipe.Ingredients.Split(',', StringSplitOptions.TrimEntries))
        {
            <li>@ingredient</li>
        }
    </ul>

    <h3 class="mt-4">Steps</h3>
    <ol>
        @foreach (var step in recipe.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries))
        {
            var text = step.TrimStart();
            if (text.Length > 2 && text[1] == '.' && char.IsDigit(text[0]))
                text = text[3..];
            else if (text.Length > 3 && text[2] == '.' && char.IsDigit(text[0]) && char.IsDigit(text[1]))
                text = text[4..];
            <li>@text.Trim()</li>
        }
    </ol>

    <a href="category/@recipe.Category" class="btn btn-secondary mt-3">← Back to @recipe.Category</a>
}

@code {
    [Parameter]
    public int Id { get; set; }

    private Recipe? recipe;

    protected override void OnParametersSet()
    {
        recipe = RecipeService.GetById(Id);
    }
}

@using RecipeHub.Services
@inject RecipeService RecipeService
@rendermode InteractiveServer

<div class="my-3 p-3 border rounded">
    <h5>Rate this recipe</h5>
    <div class="d-flex align-items-center gap-2">
        @for (int i = 1; i <= 5; i++)
        {
            var star = i;
            <button class="btn btn-link p-0 fs-4 text-decoration-none"
                    @onclick="() => SubmitRating(star)"
                    title="Rate @star stars">
                @(star <= selectedRating ? "★" : "☆")
            </button>
        }
        @if (submitted)
        {
            <span class="text-success ms-2">Thanks for rating!</span>
        }
    </div>
    <small class="text-muted">
        @if (RatingCount > 0)
        {
            @($"Average: {CurrentAverage:F1} ★ ({RatingCount} ratings)")
        }
        else
        {
            @("No ratings yet — be the first!")
        }
    </small>
</div>

@code {
    [Parameter]
    public int RecipeId { get; set; }

    [Parameter]
    public double CurrentAverage { get; set; }

    [Parameter]
    public int RatingCount { get; set; }

    private int selectedRating;
    private bool submitted;

    private void SubmitRating(int stars)
    {
        selectedRating = stars;
        RecipeService.AddRating(RecipeId, stars);
        var recipe = RecipeService.GetById(RecipeId);
        if (recipe is not null)
        {
            CurrentAverage = recipe.AverageRating;
            RatingCount = recipe.RatingCount;
        }
        submitted = true;
    }
}

@page "/submit"
@using RecipeHub.Services
@inject RecipeService RecipeService
@rendermode InteractiveServer

<PageTitle>Submit a Recipe - RecipeHub</PageTitle>

<h1>Submit a Recipe</h1>
<p>Share your favorite recipe with the community!</p>

@if (submitted)
{
    <div class="alert alert-success">
        <strong>Recipe submitted!</strong> Your recipe "@title" has been added.
        <a href="category/@category">View it in @category</a>.
    </div>
    <button class="btn btn-primary" @onclick="Reset">Submit Another</button>
}
else
{
    <EditForm Model="this" OnValidSubmit="HandleSubmit" FormName="submit-recipe">
        <div class="mb-3">
            <label for="title" class="form-label">Recipe Title</label>
            <InputText id="title" class="form-control" @bind-Value="title" placeholder="e.g., Grandma's Apple Pie" />
        </div>

        <div class="mb-3">
            <label for="category" class="form-label">Category</label>
            <InputSelect id="category" class="form-select" @bind-Value="category">
                <option value="">-- Select a category --</option>
                <option value="Italian">Italian</option>
                <option value="Indian">Indian</option>
                <option value="Mexican">Mexican</option>
                <option value="Desserts">Desserts</option>
                <option value="Other">Other</option>
            </InputSelect>
        </div>

        <div class="mb-3">
            <label for="ingredients" class="form-label">Ingredients</label>
            <InputTextArea id="ingredients" class="form-control" rows="4" @bind-Value="ingredients"
                placeholder="List ingredients separated by commas" />
        </div>

        <div class="mb-3">
            <label for="steps" class="form-label">Steps</label>
            <InputTextArea id="steps" class="form-control" rows="6" @bind-Value="steps"
                placeholder="Describe each step on a new line" />
        </div>

        @if (!string.IsNullOrEmpty(errorMessage))
        {
            <div class="alert alert-danger">@errorMessage</div>
        }

        <button type="submit" class="btn btn-primary">Submit Recipe</button>
    </EditForm>
}

@code {
    private string title = string.Empty;
    private string category = string.Empty;
    private string ingredients = string.Empty;
    private string steps = string.Empty;
    private string errorMessage = string.Empty;
    private bool submitted;

    private void HandleSubmit()
    {
        if (string.IsNullOrWhiteSpace(title) || string.IsNullOrWhiteSpace(category)
            || string.IsNullOrWhiteSpace(ingredients) || string.IsNullOrWhiteSpace(steps))
        {
            errorMessage = "Please fill in all fields.";
            return;
        }

        RecipeService.AddRecipe(title, category, ingredients, steps);
        submitted = true;
        errorMessage = string.Empty;
    }

    private void Reset()
    {
        title = string.Empty;
        category = string.Empty;
        ingredients = string.Empty;
        steps = string.Empty;
        submitted = false;
    }
}

